import base64,datetime,hashlib,json,subprocess,time,yaml

MANIFEST_B64=''
expected={'ssh_user':'kubercloud','ssh_host':'100.64.128.12','context':'kubernetes-admin@ani-kcn-full','apiserver':'https://lb.kubesphere.local:6443','cluster_id':'f39bf6e2-f3ed-4191-ada3-caeebf86c220','kube_system_uid':'3eeb5379-8748-4bf8-8f6d-d7a48ce3bc24'}
def command(args,body=None):return subprocess.run(args,input=body,capture_output=True,timeout=15)
def kubectl(*args,body=None):return command(['kubectl','--context',expected['context'],'--request-timeout=8s',*args],body)
def object_digest(value):return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def identity():
 user=command(['id','-un']).stdout.decode().strip();context=command(['kubectl','config','current-context']).stdout.decode().strip();r=kubectl('config','view','--minify','-o','json');api=json.loads(r.stdout)['clusters'][0]['cluster']['server'];r=kubectl('get','ns','kube-system','-o','json');ks=json.loads(r.stdout)['metadata']['uid'];r=kubectl('-n','ani-system','get','secret','ani-resource-private','-o','json');secret=json.loads(r.stdout);cluster=yaml.safe_load(base64.b64decode(secret['data']['config.yaml']))['network']['cluster_id'];result=dict(ssh_user=user,ssh_host='100.64.128.12',context=context,apiserver=api,cluster_id=cluster,kube_system_uid=ks)
 if result!=expected:raise RuntimeError('full designated cluster identity mismatch; no dry-run attempted')
 result['verified_at_unix']=time.time();return result
def read_object(row):
 meta=row['metadata'];args=['get',row['kind'],meta['name'],'--ignore-not-found=true','-o','json']
 if meta.get('namespace'):args=['-n',meta['namespace']]+args
 r=kubectl(*args)
 if r.returncode:raise RuntimeError('original object read failed')
 if not r.stdout.strip():return {'present':False}
 obj=json.loads(r.stdout);return {'present':True,'uid':obj['metadata'].get('uid'),'resource_version':obj['metadata'].get('resourceVersion'),'full_object_sha256':object_digest(obj)}
raw=base64.b64decode(MANIFEST_B64);manifest=json.loads(raw);assert manifest['kind']=='List' and len(manifest['items'])==21
out={'schema':'ani.modeldev.native-server-dryrun.v1','observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'ssh':'kubercloud@100.64.128.12','identity':identity(),'rendered_manifest_sha256':hashlib.sha256(raw).hexdigest(),'dry_run_only':True,'persistent_install':False,'objects':[],'limits':{'per_command_seconds':15,'stderr_bytes_per_object':16384}}
for row in manifest['items']:
 item={'kind':row['kind'],'name':row['metadata']['name'],'namespace':row['metadata'].get('namespace'),'input_object_sha256':object_digest(row),'before':read_object(row)}
 # Refresh the full target tuple before each dry-run write window.
 if time.time()-out['identity']['verified_at_unix']>50:out.setdefault('identity_refreshes',[]).append(identity())
 try:
  r=kubectl('apply','--dry-run=server','-f','-','-o','json',body=json.dumps(row,separators=(',',':')).encode());item['exit_code']=r.returncode;item['stdout_bytes']=len(r.stdout);item['stdout_sha256']=hashlib.sha256(r.stdout).hexdigest();item['stderr_bytes']=len(r.stderr);item['stderr_sha256']=hashlib.sha256(r.stderr).hexdigest();item['stderr_truncated']=len(r.stderr)>16384;item['stderr']=r.stderr[:16384].decode(errors='replace')
  if r.returncode==0:
   result=json.loads(r.stdout);item['returned_metadata']={k:result['metadata'].get(k) for k in ['name','namespace','uid','generation','resourceVersion']};item['returned_status']=result.get('status');item['result']='SERVER_DRYRUN_ACCEPTED'
  else:item['result']='SERVER_DRYRUN_REJECTED'
 except subprocess.TimeoutExpired:item.update(exit_code=None,result='COMMAND_TIMEOUT')
 item['after']=read_object(row);item['original_object_unchanged']=item['before']==item['after'];out['objects'].append(item)
out['summary']={'object_count':len(out['objects']),'accepted':sum(r['result']=='SERVER_DRYRUN_ACCEPTED' for r in out['objects']),'rejected':sum(r['result']=='SERVER_DRYRUN_REJECTED' for r in out['objects']),'timeouts':sum(r['result']=='COMMAND_TIMEOUT' for r in out['objects']),'all_original_objects_unchanged':all(r['original_object_unchanged'] for r in out['objects']),'scope':'schema/admission/CEL validation visible during server dry-run only; not installed typeChecking, AD01/AD02 or LIVE02 behavior acceptance'}
print(json.dumps(out,indent=2))
